CREATE TABLE users(id INTEGER PRIMARY KEY AUTOINCREMENT, phone TEXT UNIQUE, email TEXT, name TEXT, role TEXT, city TEXT, wallet_balance REAL DEFAULT 0, password_hash TEXT, google_id TEXT, apple_id TEXT, photo_url TEXT, referral_code TEXT, otp_code TEXT, otp_expires_at TEXT, otp_attempts INT DEFAULT 0, otp_last_sent TEXT, is_blacklisted INT DEFAULT 0, blacklist_reason TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE drivers(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INT, status TEXT DEFAULT 'pending', is_online INT DEFAULT 0, rating REAL DEFAULT 5, total_trips INT DEFAULT 0, bank_name TEXT, account_number TEXT, account_name TEXT);
CREATE TABLE cars(id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT, car_type TEXT, category TEXT, city TEXT, plate_number TEXT, color TEXT, year INT, make TEXT, model TEXT, transmission TEXT, fuel_type TEXT, seats INT, mileage_limit_per_day INT, security_deposit REAL DEFAULT 0, driver_id INT, description TEXT, availability_status TEXT DEFAULT 'available', is_available INT DEFAULT 1, surge_multiplier REAL DEFAULT 1, expected_return_at TEXT, created_by_admin INT DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE car_media(id INTEGER PRIMARY KEY AUTOINCREMENT, car_id INT, media_type TEXT, url TEXT, status TEXT, sort_order INT DEFAULT 0, rejection_reason TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE car_location_pricing(id INTEGER PRIMARY KEY AUTOINCREMENT, car_id INT, location TEXT, price REAL);
CREATE TABLE pricing(id INTEGER PRIMARY KEY AUTOINCREMENT, city TEXT, booking_type TEXT, base_price REAL, per_km_price REAL, per_hour_price REAL, per_day_price REAL);
CREATE TABLE bookings(id INTEGER PRIMARY KEY AUTOINCREMENT, customer_id INT, driver_id INT, car_id INT, booking_type TEXT, car_type TEXT, status TEXT DEFAULT 'pending', pickup_address TEXT, dropoff_address TEXT, pickup_coords TEXT, dropoff_coords TEXT, duration_hours REAL, duration_days INT, total_price REAL, security_deposit REAL DEFAULT 0, commission_amount REAL, city TEXT, start_time TEXT, end_time TEXT, payment_status TEXT DEFAULT 'unpaid', deposit_released INT DEFAULT 0, deposit_refund_amount REAL, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE payments(id INTEGER PRIMARY KEY AUTOINCREMENT, booking_id INT, booking_kind TEXT DEFAULT 'website', amount REAL, deposit_amount REAL, method TEXT, status TEXT, is_test INT DEFAULT 0, paystack_reference TEXT, provider_reference TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE notifications(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INT, title TEXT, body TEXT, type TEXT, is_read INT DEFAULT 0, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE driver_locations(id INTEGER PRIMARY KEY AUTOINCREMENT, driver_id INT, lat REAL, lng REAL, heading REAL, booking_id INT, updated_at TEXT);
CREATE TABLE wishlists(id INTEGER PRIMARY KEY AUTOINCREMENT, user_id INT, car_id INT);

CREATE TABLE IF NOT EXISTS promo_codes(id INTEGER PRIMARY KEY AUTOINCREMENT, code TEXT, is_active INT DEFAULT 1, max_uses INT, used_count INT DEFAULT 0, expiry_date TEXT, discount_percent REAL);
CREATE TABLE IF NOT EXISTS event_packages(id INTEGER PRIMARY KEY AUTOINCREMENT, event_key TEXT, package_key TEXT, name TEXT, tagline TEXT, sort_order INT DEFAULT 0);
CREATE TABLE IF NOT EXISTS event_package_pricing(id INTEGER PRIMARY KEY AUTOINCREMENT, package_id INT, location TEXT, price REAL);
CREATE TABLE IF NOT EXISTS event_bookings(id INTEGER PRIMARY KEY AUTOINCREMENT, event_key TEXT, event_name TEXT, pickup_address TEXT, dropoff_address TEXT, pickup_zone TEXT, normalized_zone TEXT, pickup_lng REAL, pickup_lat REAL, event_date TEXT, date_display TEXT, pickup_time TEXT, passengers INT, ride_type TEXT, package_id TEXT, bus_route_id TEXT, car_id INT, selected_car TEXT, price REAL, discount_code TEXT, discount_percent REAL, final_price REAL, status TEXT, created_at TEXT DEFAULT CURRENT_TIMESTAMP);
